export const userFixture = (kind = 'customer', id = 7, status = 'active') => ({ user_id: id, full_name: kind + ' Example ' + id, email: kind + id + '@example.com', platform_role: kind, account_status: status, created_at: '2026-11-07T08:00:00' });
export const driverFixture = (id = 7, approval = 'pending', status = 'active') => ({ ...userFixture('driver', id, status), profile: { approval_status: approval, vehicle_type: 'van', registration_reference: 'TEST-123', reviewed_by: approval === 'pending' ? null : 90, reviewed_at: approval === 'pending' ? null : '2026-11-07T09:00:00' }, verification: { driver_user_id: id, legacy_exempt: false, approval_ready: approval === 'pending', documents: ['DRIVING_LICENCE', 'VEHICLE_OWNERSHIP_PROOF'].map((kind, index) => ({ document_type: kind, document_id: `00000000-0000-4000-8000-${String(id * 2 + index).padStart(12, '0')}`, version: 1, review_status: 'APPROVED', integrity_valid: true, media_type: 'image/png' })) } });
export const businessFixture = (id = 7, approval = 'pending') => ({ business_id: id, business_name: 'Example business ' + id, business_type: 'retail', registration_number: 'REG-123', phone: '0771234567', address: 'Example area', approval_status: approval, created_at: '2026-11-07T08:00:00', owners: [{ user_id: 8, full_name: 'Owner Example', email: 'owner@example.com', phone: null }] });
export const rowFixture = (kind, id = 7) => kind === 'business' ? businessFixture(id) : kind === 'driver' ? driverFixture(id) : userFixture(kind, id);
export const associationFixture = userId => ({ user_id: userId, limit: 10, offset: 0, total: 1, businesses: [{ business_id: 20, business_name: 'Associated business', approval_status: 'approved', membership_status: 'active', business_role: 'owner' }] });
export const historyFixture = businessId => ({ business_id: businessId, limit: 10, offset: 0, total: 0, history: [] });
